const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const clinic_name = text(input.clinic_name);
const client_name = text(input.client_name);
const channel = text(input.channel).toLowerCase();
const api_key = text(input.api_key);
const source_ip = text(input.source_ip);
const signature_verified = bool(input.signature_verified);
const verification_reference = text(input.verification_reference);
const confirm_check = bool(input.confirm_check);

const channels = [
  'whatsapp',
  'sms',
  'phone',
  'telegram',
  'webchat',
  'manual',
  'api',
  'email',
  'web_push',
  'in_app',
];

const errors = [];

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (!client_name) {
  errors.push({
    field: 'client_name',
    message: 'نام Gateway Client الزامی است.',
  });
}

if (!channels.includes(channel)) {
  errors.push({
    field: 'channel',
    message: 'کانال معتبر نیست.',
  });
}

if (confirm_check !== true) {
  errors.push({
    field: 'confirm_check',
    message: 'بررسی Authentication باید تأیید شود.',
  });
}

return [{
  json: {
    clinic_name,
    client_name,
    channel,
    api_key,
    source_ip,
    signature_verified,
    verification_reference,
    confirm_check,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];
